1	import { formatCurrency } from '@/functions/formaters/formatCurrency';
2	import numberFormat from '@/functions/formaters/numberFormat';
3	import { getSliderThumbOffsetStyle } from '@/functions/slider/getSliderThumbOffsetStyle';
4	import { sendToastMessage } from '@/functions/messages/toastMessage';
5	import { useIsLocalhost } from '@/lib/runtime/is-localhost';
6	import { cn } from '@/lib/utils';
7	import { saveProposalAndComission } from '@/services/BrokerServices';
8	import { useSmartBlockHistoricalSuggestionsQuery } from '@/hooks/queries/smart-block-historical-suggestions';
9	import { LeadMagnetResposeProps } from '@/types/leadMagnet';
10	import { OficioProposta } from '@/types/oficio';
11	import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
12	import {
13	    Loader2,
14	    Save,
15	    BrainCircuit,
16	    Sparkles,
17	    Coins,
18	    Percent,
19	    Scale,
20	    AlertCircle,
21	} from 'lucide-react';
22	import { Button } from '../Button';
23	import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '../ui/tooltip';
24	import { PERCENTAGE_FACTOR, PROPOSAL_MATCH_THRESHOLD, SLIDER_STEP, TOOLTIP_DELAY_MS } from './constants';
25	
26	type TSliderInputField = 'proposal' | 'commissionBroker' | 'commissionCoordinator';
27	
28	type TSliderValues = {
29	    proposal: number;
30	    commissionBroker: number;
31	    commissionCoordinator: number;
32	};
33	
34	interface INormalizedSliderData {
35	    proposta_id: number;
36	    min_proposal: number;
37	    max_proposal: number;
38	    min_comission: number;
39	    max_comission: number;
40	    valor_minimo_de_comissao_coordenador: number;
41	    valor_maximo_de_comissao_coordenador: number;
42	}
43	
44	interface ILeadMagnetSliderProps {
45	    backendResponse: LeadMagnetResposeProps | OficioProposta | null;
46	}
47	
48	const normalizeResponse = (
49	    data: LeadMagnetResposeProps | OficioProposta | null,
50	): INormalizedSliderData | null => {
51	    if (!data) return null;
52	
53	    if ('proposta_minima' in data) {
54	        return {
55	            proposta_id: data.id,
56	            min_proposal: parseFloat(data.proposta_minima),
57	            max_proposal: parseFloat(data.proposta_maxima),
58	            min_comission: parseFloat(data.comissao_minima),
59	            max_comission: parseFloat(data.comissao_maxima),
60	            valor_minimo_de_comissao_coordenador: parseFloat(data.comissao_minima_coordenador || '0') || 0,
61	            valor_maximo_de_comissao_coordenador: parseFloat(data.comissao_maxima_coordenador || '0') || 0,
62	        };
63	    }
64	
65	    return {
66	        proposta_id: data.proposta_id,
67	        min_proposal: data.min_proposal,
68	        max_proposal: data.max_proposal,
69	        min_comission: data.min_comission,
70	        max_comission: data.max_comission,
71	        valor_minimo_de_comissao_coordenador: data.valor_minimo_de_comissao_coordenador || 0,
72	        valor_maximo_de_comissao_coordenador: data.valor_maximo_de_comissao_coordenador || 0,
73	    };
74	};
75	
76	const extractSmartBlockId = (data: LeadMagnetResposeProps | OficioProposta | null): number | string | null => {
77	    if (!data) return null;
78	    if ('smart_block_id' in data && data.smart_block_id) {
79	        return data.smart_block_id;
80	    }
81	    if ('smart_block' in data && data.smart_block) {
82	        return data.smart_block;
83	    }
84	    return null;
85	};
86	
87	const LeadMagnetSlider = ({ backendResponse }: ILeadMagnetSliderProps) => {
88	    const isLocalhost = useIsLocalhost();
89	
90	    const normalizedData = useMemo(() => normalizeResponse(backendResponse), [backendResponse]);
91	
92	    const [errorMessage, setErrorMessage] = useState<boolean>(false);
93	    const [isProposalButtonDisabled, setIsProposalButtonDisabled] = useState<boolean>(true);
94	    const [savingProposalAndComission, setSavingProposalAndComission] = useState<boolean>(false);
95	
96	    const [sliderValues, setSliderValues] = useState<TSliderValues>({
97	        proposal: 0,
98	        commissionBroker: 0,
99	        commissionCoordinator: 0,
100	    });
101	    const [auxValues, setAuxValues] = useState<TSliderValues>({
102	        proposal: 0,
103	        commissionBroker: 0,
104	        commissionCoordinator: 0,
105	    });
106	    const { data: suggestions } = useSmartBlockHistoricalSuggestionsQuery(
107	        isLocalhost ? extractSmartBlockId(backendResponse) : null,
108	    );
109	
110	    const brokerMin = normalizedData?.min_comission || 0;
111	    const brokerMax = normalizedData?.max_comission || 0;
112	    const coordMin = normalizedData?.valor_minimo_de_comissao_coordenador || 0;
113	    const coordMax = normalizedData?.valor_maximo_de_comissao_coordenador || 0;
114	
115	    const suggestedProposal = useMemo(() => {
116	        if (!normalizedData) return 0;
117	        const raw = suggestions?.suggested_proposal;
118	        if (raw == null || raw <= 0) return 0;
119	        return Math.min(Math.max(raw, normalizedData.min_proposal), normalizedData.max_proposal);
120	    }, [suggestions, normalizedData]);
121	
122	    const suggestedCommissions = useMemo(() => {
123	        if (!normalizedData || suggestedProposal === 0) return { broker: 0, coordinator: 0 };
124	
125	        const proportion =
126	            (suggestedProposal - normalizedData.min_proposal) /
127	            (normalizedData.max_proposal - normalizedData.min_proposal);
128	
129	        const broker =
130	            normalizedData.max_comission -
131	            proportion * (normalizedData.max_comission - normalizedData.min_comission);
132	
133	        const brokerProportion = (broker - brokerMin) / (brokerMax - brokerMin);
134	
135	        let coordinator = normalizedData.valor_minimo_de_comissao_coordenador;
136	        if (coordMin > 0 && coordMax > 0) {
137	            coordinator = coordMin + brokerProportion * (coordMax - coordMin);
138	        }
139	
140	        return { broker, coordinator };
141	    }, [suggestedProposal, normalizedData, brokerMin, brokerMax, coordMin, coordMax]);
142	
143	    const proposalSuggestionPct = useMemo(() => {
144	        if (!normalizedData) return 0;
145	        const range = normalizedData.max_proposal - normalizedData.min_proposal;
146	        if (range <= 0) return 0;
147	        return Math.max(0, Math.min(PERCENTAGE_FACTOR, ((suggestedProposal - normalizedData.min_proposal) / range) * PERCENTAGE_FACTOR));
148	    }, [normalizedData, suggestedProposal]);
149	
150	    const commissionSuggestionPct = useMemo(() => {
151	        if (!normalizedData) return 0;
152	        const range = normalizedData.max_comission - normalizedData.min_comission;
153	        if (range <= 0) return 0;
154	        return Math.max(0, Math.min(PERCENTAGE_FACTOR, ((suggestedCommissions.broker - normalizedData.min_comission) / range) * PERCENTAGE_FACTOR));
155	    }, [normalizedData, suggestedCommissions]);
156	
157	    const proposalRef = useRef<HTMLInputElement | null>(null);
158	    const commissionBrokerRef = useRef<HTMLInputElement | null>(null);
159	    const commissionCoordinatorRef = useRef<HTMLInputElement | null>(null);
160	
161	    const handleProposalSliderChange = (value: string, sliderChange: boolean) => {
162	        if (!normalizedData) return;
163	
164	        const newProposalSliderValue = parseFloat(value);
165	
166	        if (newProposalSliderValue !== auxValues.proposal) {
167	            setIsProposalButtonDisabled(false);
168	        } else {
169	            setIsProposalButtonDisabled(true);
170	        }
171	
172	        const proportion =
173	            (newProposalSliderValue - normalizedData.min_proposal) /
174	            (normalizedData.max_proposal - normalizedData.min_proposal);
175	
176	        const newCommissionBrokerSliderValue =
177	            normalizedData.max_comission -
178	            proportion * (normalizedData.max_comission - normalizedData.min_comission);
179	
180	        const brokerProportion =
181	            (newCommissionBrokerSliderValue - brokerMin) / (brokerMax - brokerMin);
182	
183	        let newCommissionCoordinatorSliderValue: number | undefined;
184	        if (coordMin > 0 && coordMax > 0) {
185	            newCommissionCoordinatorSliderValue =
186	                coordMin + brokerProportion * (coordMax - coordMin);
187	        }
188	
189	        setSliderValues({
190	            proposal: newProposalSliderValue,
191	            commissionBroker: newCommissionBrokerSliderValue,
192	            commissionCoordinator: newCommissionCoordinatorSliderValue || 0,
193	        });
194	
195	        if (commissionBrokerRef.current && proposalRef.current) {
196	            commissionBrokerRef.current.value = numberFormat(newCommissionBrokerSliderValue);
197	            if (sliderChange) {
198	                proposalRef.current.value = numberFormat(newProposalSliderValue);
199	            }
200	        }
201	    };
202	
203	    const handleComissionBrokerSliderChange = (value: string, sliderChange: boolean) => {
204	        if (!normalizedData) return;
205	
206	        const newCommissionBrokerSliderValue = parseFloat(value);
207	
208	        if (newCommissionBrokerSliderValue !== auxValues.commissionBroker) {
209	            setIsProposalButtonDisabled(false);
210	        } else {
211	            setIsProposalButtonDisabled(true);
212	        }
213	
214	        const proportion =
215	            (newCommissionBrokerSliderValue - normalizedData.min_comission) /
216	            (normalizedData.max_comission - normalizedData.min_comission);
217	
218	        const newProposalSliderValue =
219	            normalizedData.max_proposal -
220	            proportion * (normalizedData.max_proposal - normalizedData.min_proposal);
221	
222	        const brokerProportion =
223	            (newCommissionBrokerSliderValue - brokerMin) / (brokerMax - brokerMin);
224	
225	        let newCommissionCoordinatorSliderValue: number | undefined;
226	        if (coordMin > 0 && coordMax > 0) {
227	            newCommissionCoordinatorSliderValue =
228	                coordMin + brokerProportion * (coordMax - coordMin);
229	        }
230	
231	        setSliderValues({
232	            proposal: newProposalSliderValue,
233	            commissionBroker: newCommissionBrokerSliderValue,
234	            commissionCoordinator: newCommissionCoordinatorSliderValue || 0,
235	        });
236	
237	        if (proposalRef.current && commissionBrokerRef.current) {
238	            proposalRef.current.value = numberFormat(newProposalSliderValue);
239	            if (sliderChange) {
240	                commissionBrokerRef.current.value = numberFormat(newCommissionBrokerSliderValue);
241	            }
242	        }
243	    };
244	
245	    const handleComissionCoordinatorSliderChange = (value: string, sliderChange: boolean) => {
246	        if (!normalizedData) return;
247	
248	        const newComissionCoordinatorSliderValue = parseFloat(value);
249	
250	        if (newComissionCoordinatorSliderValue !== auxValues.commissionCoordinator) {
251	            setIsProposalButtonDisabled(false);
252	        } else {
253	            setIsProposalButtonDisabled(true);
254	        }
255	
256	        const coordinatorProportion =
257	            (newComissionCoordinatorSliderValue - coordMin) / (coordMax - coordMin);
258	
259	        const newCommissionBrokerSliderValue =
260	            brokerMin + coordinatorProportion * (brokerMax - brokerMin);
261	
262	        const proportion =
263	            (newCommissionBrokerSliderValue - normalizedData.min_comission) /
264	            (normalizedData.max_comission - normalizedData.min_comission);
265	
266	        const newProposalSliderValue =
267	            normalizedData.max_proposal -
268	            proportion * (normalizedData.max_proposal - normalizedData.min_proposal);
269	
270	        setSliderValues({
271	            proposal: newProposalSliderValue,
272	            commissionBroker: newCommissionBrokerSliderValue,
273	            commissionCoordinator: newComissionCoordinatorSliderValue,
274	        });
275	
276	        if (
277	            proposalRef.current &&
278	            commissionBrokerRef.current &&
279	            commissionCoordinatorRef.current
280	        ) {
281	            proposalRef.current.value = numberFormat(newProposalSliderValue);
282	            commissionBrokerRef.current.value = numberFormat(newCommissionBrokerSliderValue);
283	            if (sliderChange) {
284	                commissionCoordinatorRef.current.value = numberFormat(
285	                    newComissionCoordinatorSliderValue,
286	                );
287	            }
288	        }
289	    };
290	
291	    const changeInputValues = (inputField: TSliderInputField, value: string) => {
292	        if (!normalizedData) return;
293	
294	        const rawValue = value
295	            .replace(/R\$\s*/g, '')
296	            .replaceAll('.', '')
297	            .replaceAll(',', '.');
298	
299	        const numericalValue = parseFloat(rawValue);
300	
301	        switch (inputField) {
302	            case 'proposal':
303	                if (
304	                    numericalValue >= normalizedData.min_proposal &&
305	                    numericalValue <= normalizedData.max_proposal &&
306	                    !isNaN(numericalValue) &&
307	                    numericalValue !== auxValues.proposal
308	                ) {
309	                    setIsProposalButtonDisabled(false);
310	                } else {
311	                    setIsProposalButtonDisabled(true);
312	                }
313	
314	                if (
315	                    numericalValue < normalizedData.min_proposal ||
316	                    numericalValue > normalizedData.max_proposal ||
317	                    isNaN(numericalValue)
318	                ) {
319	                    setErrorMessage(true);
320	                    return;
321	                } else {
322	                    setErrorMessage(false);
323	                }
324	
325	                setSliderValues((old) => ({
326	                    ...old,
327	                    proposal: numericalValue,
328	                }));
329	                handleProposalSliderChange(rawValue, false);
330	                break;
331	
332	            case 'commissionBroker':
333	                if (
334	                    numericalValue >= normalizedData.min_comission &&
335	                    numericalValue <= normalizedData.max_comission &&
336	                    !isNaN(numericalValue) &&
337	                    numericalValue !== auxValues.commissionBroker
338	                ) {
339	                    setIsProposalButtonDisabled(false);
340	                } else {
341	                    setIsProposalButtonDisabled(true);
342	                }
343	
344	                if (
345	                    numericalValue < normalizedData.min_comission ||
346	                    numericalValue > normalizedData.max_comission ||
347	                    isNaN(numericalValue)
348	                ) {
349	                    setErrorMessage(true);
350	                    return;
351	                } else {
352	                    setErrorMessage(false);
353	                }
354	
355	                setSliderValues((old) => ({
356	                    ...old,
357	                    commissionBroker: numericalValue,
358	                }));
359	                handleComissionBrokerSliderChange(rawValue, false);
360	                break;
361	
362	            case 'commissionCoordinator':
363	                if (
364	                    numericalValue >= normalizedData.valor_minimo_de_comissao_coordenador &&
365	                    numericalValue <= normalizedData.valor_maximo_de_comissao_coordenador &&
366	                    !isNaN(numericalValue) &&
367	                    numericalValue !== auxValues.commissionCoordinator
368	                ) {
369	                    setIsProposalButtonDisabled(false);
370	                } else {
371	                    setIsProposalButtonDisabled(true);
372	                }
373	
374	                if (
375	                    numericalValue < normalizedData.valor_minimo_de_comissao_coordenador ||
376	                    numericalValue > normalizedData.valor_maximo_de_comissao_coordenador ||
377	                    isNaN(numericalValue)
378	                ) {
379	                    setErrorMessage(true);
380	                    return;
381	                } else {
382	                    setErrorMessage(false);
383	                }
384	
385	                setSliderValues((old) => ({
386	                    ...old,
387	                    commissionCoordinator: numericalValue,
388	                }));
389	                handleComissionCoordinatorSliderChange(rawValue, false);
390	                break;
391	
392	            default:
393	                break;
394	        }
395	    };
396	
397	    const handleSaveProposalAndComission = async () => {
398	        if (!normalizedData) return;
399	        setSavingProposalAndComission(true);
400	        try {
401	            await saveProposalAndComission(normalizedData.proposta_id, sliderValues);
402	
403	            sendToastMessage({
404	                title: 'Proposta e comissão salvas com sucesso!',
405	                type: 'success',
406	            });
407	            setIsProposalButtonDisabled(true);
408	            setAuxValues(sliderValues);
409	        } catch {
410	            sendToastMessage({
411	                title: 'Erro ao salvar proposta e comissão!',
412	                type: 'error',
413	            });
414	        }
415	        setSavingProposalAndComission(false);
416	    };
417	
418	    const handleApplySuggestion = useCallback(() => {
419	        if (!normalizedData) return;
420	
421	        const newValues = {
422	            proposal: Math.min(
423	                Math.max(suggestedProposal, normalizedData.min_proposal),
424	                normalizedData.max_proposal,
425	            ),
426	            commissionBroker: Math.min(
427	                Math.max(suggestedCommissions.broker, normalizedData.min_comission),
428	                normalizedData.max_comission,
429	            ),
430	            commissionCoordinator: Math.min(
431	                Math.max(
432	                    suggestedCommissions.coordinator,
433	                    normalizedData.valor_minimo_de_comissao_coordenador,
434	                ),
435	                normalizedData.valor_maximo_de_comissao_coordenador,
436	            ),
437	        };
438	
439	        setSliderValues(newValues);
440	        setIsProposalButtonDisabled(
441	            newValues.proposal === auxValues.proposal &&
442	                newValues.commissionBroker === auxValues.commissionBroker &&
443	                newValues.commissionCoordinator === auxValues.commissionCoordinator,
444	        );
445	
446	        if (proposalRef.current && commissionBrokerRef.current) {
447	            proposalRef.current.value = numberFormat(newValues.proposal);
448	            commissionBrokerRef.current.value = numberFormat(newValues.commissionBroker);
449	            if (commissionCoordinatorRef.current) {
450	                commissionCoordinatorRef.current.value = numberFormat(newValues.commissionCoordinator);
451	            }
452	        }
453	    }, [normalizedData, suggestedProposal, suggestedCommissions, auxValues]);
454	
455	    const isAtSuggestion = useMemo(() => {
456	        return Math.abs(sliderValues.proposal - suggestedProposal) < PROPOSAL_MATCH_THRESHOLD;
457	    }, [sliderValues.proposal, suggestedProposal]);
458	
459	    const isAtMin = useMemo(() => {
460	        return normalizedData
461	            ? Math.abs(sliderValues.proposal - normalizedData.min_proposal) < PROPOSAL_MATCH_THRESHOLD
462	            : false;
463	    }, [sliderValues.proposal, normalizedData]);
464	
465	    const isAtMax = useMemo(() => {
466	        return normalizedData
467	            ? Math.abs(sliderValues.proposal - normalizedData.max_proposal) < PROPOSAL_MATCH_THRESHOLD
468	            : false;
469	    }, [sliderValues.proposal, normalizedData]);
470	
471	    useEffect(() => {
472	        if (!normalizedData) return;
473	
474	        const initialProposal = suggestions
475	            ? Math.min(
476	                  Math.max(suggestedProposal, normalizedData.min_proposal),
477	                  normalizedData.max_proposal,
478	              )
479	            : normalizedData.max_proposal;
480	
481	        const initialCommission = suggestions
482	            ? Math.min(
483	                  Math.max(suggestedCommissions.broker, normalizedData.min_comission),
484	                  normalizedData.max_comission,
485	              )
486	            : normalizedData.min_comission;
487	
488	        const brokerProportion =
489	            brokerMax > brokerMin ? (initialCommission - brokerMin) / (brokerMax - brokerMin) : 0;
490	        const initialCoordinator =
491	            suggestions && coordMin > 0 && coordMax > 0
492	                ? Math.min(
493	                      Math.max(
494	                          suggestedCommissions.coordinator,
495	                          normalizedData.valor_minimo_de_comissao_coordenador,
496	                      ),
497	                      normalizedData.valor_maximo_de_comissao_coordenador,
498	                  )
499	                : coordMin + brokerProportion * (coordMax - coordMin);
500	
501	        setSliderValues({
502	            proposal: initialProposal,
503	            commissionBroker: initialCommission,
504	            commissionCoordinator: initialCoordinator,
505	        });
506	
507	        setAuxValues({
508	            proposal: initialProposal,
509	            commissionBroker: initialCommission,
510	            commissionCoordinator: initialCoordinator,
511	        });
512	
513	        if (proposalRef.current && commissionBrokerRef.current) {
514	            proposalRef.current.value = numberFormat(initialProposal);
515	            commissionBrokerRef.current.value = numberFormat(initialCommission);
516	            if (commissionCoordinatorRef.current) {
517	                commissionCoordinatorRef.current.value = numberFormat(initialCoordinator);
518	            }
519	        }
520	    }, [
521	        normalizedData,
522	        suggestions,
523	        suggestedProposal,
524	        suggestedCommissions,
525	        brokerMin,
526	        brokerMax,
527	        coordMin,
528	        coordMax,
529	    ]);
530	
531	    const proposalProportionPct = useMemo(() => {
532	        if (!normalizedData) return 0;
533	        const range = normalizedData.max_proposal - normalizedData.min_proposal;
534	        if (range <= 0) return 0;
535	        return Math.round(
536	            Math.max(0, Math.min(PERCENTAGE_FACTOR, ((sliderValues.proposal - normalizedData.min_proposal) / range) * PERCENTAGE_FACTOR)),
537	        );
538	    }, [normalizedData, sliderValues.proposal]);
539	
540	    if (!normalizedData) return null;
541	
542	    return (
543	        <TooltipProvider delayDuration={TOOLTIP_DELAY_MS}>
544	            <div className="flex w-full flex-col gap-5">
545	                {/* Header com contexto SmartBlock */}
546	                <div className="flex flex-col gap-3 rounded-2xl border border-border/70 bg-card p-4 shadow-xs sm:p-5">
547	                    <div className="flex items-center gap-3">
548	                        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary/10 text-primary">
549	                            <BrainCircuit className="h-5 w-5" />
550	                        </div>
551	                        <div>
552	                            <div className="flex items-center gap-2">
553	                                <h2 className="font-nexa text-base font-extrabold uppercase tracking-wide text-foreground">
554	                                    Simulação de Proposta &amp; Comissão
555	                                </h2>
556	                            </div>
557	                            <p className="font-satoshi text-xs text-muted-foreground">
558	                                Ajuste proporcional calculado via motor de precificação SmartBlock
559	                            </p>
560	                        </div>
561	                    </div>
562	
563	                    {/* Presets Rápidos */}
564	                    <div className="flex flex-wrap items-center gap-1.5 pt-1 border-t border-border/50">
565	                        <span className="text-[11px] font-semibold text-muted-foreground mr-1">
566	                            Atalhos:
567	                        </span>
568	
569	                        {isLocalhost && (
570	                            <Tooltip>
571	                                <TooltipTrigger asChild>
572	                                    <button
573	                                        type="button"
574	                                        onClick={handleApplySuggestion}
575	                                        className={cn(
