import { formatCurrency } from '@/functions/formaters/formatCurrency';
import numberFormat from '@/functions/formaters/numberFormat';
import { getSliderThumbOffsetStyle } from '@/functions/slider/getSliderThumbOffsetStyle';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { useIsLocalhost } from '@/lib/runtime/is-localhost';
import { cn } from '@/lib/utils';
import { saveProposalAndComission } from '@/services/BrokerServices';
import { useSmartBlockHistoricalSuggestionsQuery } from '@/hooks/queries/smart-block-historical-suggestions';
import { LeadMagnetResposeProps } from '@/types/leadMagnet';
import { OficioProposta } from '@/types/oficio';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
    Loader2,
    Save,
    BrainCircuit,
    Sparkles,
    Coins,
    Percent,
    Scale,
    AlertCircle,
} from 'lucide-react';
import { Button } from '../Button';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '../ui/tooltip';
import { PERCENTAGE_FACTOR, PROPOSAL_MATCH_THRESHOLD, SLIDER_STEP, TOOLTIP_DELAY_MS } from './constants';

type TSliderInputField = 'proposal' | 'commissionBroker' | 'commissionCoordinator';

type TSliderValues = {
    proposal: number;
    commissionBroker: number;
    commissionCoordinator: number;
};

interface INormalizedSliderData {
    proposta_id: number;
    min_proposal: number;
    max_proposal: number;
    min_comission: number;
    max_comission: number;
    valor_minimo_de_comissao_coordenador: number;
    valor_maximo_de_comissao_coordenador: number;
}

interface ILeadMagnetSliderProps {
    backendResponse: LeadMagnetResposeProps | OficioProposta | null;
}

const normalizeResponse = (
    data: LeadMagnetResposeProps | OficioProposta | null,
): INormalizedSliderData | null => {
    if (!data) return null;

    if ('proposta_minima' in data) {
        return {
            proposta_id: data.id,
            min_proposal: parseFloat(data.proposta_minima),
            max_proposal: parseFloat(data.proposta_maxima),
            min_comission: parseFloat(data.comissao_minima),
            max_comission: parseFloat(data.comissao_maxima),
            valor_minimo_de_comissao_coordenador: parseFloat(data.comissao_minima_coordenador || '0') || 0,
            valor_maximo_de_comissao_coordenador: parseFloat(data.comissao_maxima_coordenador || '0') || 0,
        };
    }

    return {
        proposta_id: data.proposta_id,
        min_proposal: data.min_proposal,
        max_proposal: data.max_proposal,
        min_comission: data.min_comission,
        max_comission: data.max_comission,
        valor_minimo_de_comissao_coordenador: data.valor_minimo_de_comissao_coordenador || 0,
        valor_maximo_de_comissao_coordenador: data.valor_maximo_de_comissao_coordenador || 0,
    };
};

const extractSmartBlockId = (data: LeadMagnetResposeProps | OficioProposta | null): number | string | null => {
    if (!data) return null;
    if ('smart_block_id' in data && data.smart_block_id) {
        return data.smart_block_id;
    }
    if ('smart_block' in data && data.smart_block) {
        return data.smart_block;
    }
    return null;
};

const LeadMagnetSlider = ({ backendResponse }: ILeadMagnetSliderProps) => {
    const isLocalhost = useIsLocalhost();

    const normalizedData = useMemo(() => normalizeResponse(backendResponse), [backendResponse]);

    const [errorMessage, setErrorMessage] = useState<boolean>(false);
    const [isProposalButtonDisabled, setIsProposalButtonDisabled] = useState<boolean>(true);
    const [savingProposalAndComission, setSavingProposalAndComission] = useState<boolean>(false);

    const [sliderValues, setSliderValues] = useState<TSliderValues>({
        proposal: 0,
        commissionBroker: 0,
        commissionCoordinator: 0,
    });
    const [auxValues, setAuxValues] = useState<TSliderValues>({
        proposal: 0,
        commissionBroker: 0,
        commissionCoordinator: 0,
    });
    const { data: suggestions } = useSmartBlockHistoricalSuggestionsQuery(
        isLocalhost ? extractSmartBlockId(backendResponse) : null,
    );

    const brokerMin = normalizedData?.min_comission || 0;
    const brokerMax = normalizedData?.max_comission || 0;
    const coordMin = normalizedData?.valor_minimo_de_comissao_coordenador || 0;
    const coordMax = normalizedData?.valor_maximo_de_comissao_coordenador || 0;

    const suggestedProposal = useMemo(() => {
        if (!normalizedData) return 0;
        const raw = suggestions?.suggested_proposal;
        if (raw == null || raw <= 0) return 0;
        return Math.min(Math.max(raw, normalizedData.min_proposal), normalizedData.max_proposal);
    }, [suggestions, normalizedData]);

    const suggestedCommissions = useMemo(() => {
        if (!normalizedData || suggestedProposal === 0) return { broker: 0, coordinator: 0 };

        const proportion =
            (suggestedProposal - normalizedData.min_proposal) /
            (normalizedData.max_proposal - normalizedData.min_proposal);

        const broker =
            normalizedData.max_comission -
            proportion * (normalizedData.max_comission - normalizedData.min_comission);

        const brokerProportion = (broker - brokerMin) / (brokerMax - brokerMin);

        let coordinator = normalizedData.valor_minimo_de_comissao_coordenador;
        if (coordMin > 0 && coordMax > 0) {
            coordinator = coordMin + brokerProportion * (coordMax - coordMin);
        }

        return { broker, coordinator };
    }, [suggestedProposal, normalizedData, brokerMin, brokerMax, coordMin, coordMax]);

    const proposalSuggestionPct = useMemo(() => {
        if (!normalizedData) return 0;
        const range = normalizedData.max_proposal - normalizedData.min_proposal;
        if (range <= 0) return 0;
        return Math.max(0, Math.min(PERCENTAGE_FACTOR, ((suggestedProposal - normalizedData.min_proposal) / range) * PERCENTAGE_FACTOR));
    }, [normalizedData, suggestedProposal]);

    const commissionSuggestionPct = useMemo(() => {
        if (!normalizedData) return 0;
        const range = normalizedData.max_comission - normalizedData.min_comission;
        if (range <= 0) return 0;
        return Math.max(0, Math.min(PERCENTAGE_FACTOR, ((suggestedCommissions.broker - normalizedData.min_comission) / range) * PERCENTAGE_FACTOR));
    }, [normalizedData, suggestedCommissions]);

    const proposalRef = useRef<HTMLInputElement | null>(null);
    const commissionBrokerRef = useRef<HTMLInputElement | null>(null);
    const commissionCoordinatorRef = useRef<HTMLInputElement | null>(null);

    const handleProposalSliderChange = (value: string, sliderChange: boolean) => {
        if (!normalizedData) return;

        const newProposalSliderValue = parseFloat(value);

        if (newProposalSliderValue !== auxValues.proposal) {
            setIsProposalButtonDisabled(false);
        } else {
            setIsProposalButtonDisabled(true);
        }

        const proportion =
            (newProposalSliderValue - normalizedData.min_proposal) /
            (normalizedData.max_proposal - normalizedData.min_proposal);

        const newCommissionBrokerSliderValue =
            normalizedData.max_comission -
            proportion * (normalizedData.max_comission - normalizedData.min_comission);

        const brokerProportion =
            (newCommissionBrokerSliderValue - brokerMin) / (brokerMax - brokerMin);

        let newCommissionCoordinatorSliderValue: number | undefined;
        if (coordMin > 0 && coordMax > 0) {
            newCommissionCoordinatorSliderValue =
                coordMin + brokerProportion * (coordMax - coordMin);
        }

        setSliderValues({
            proposal: newProposalSliderValue,
            commissionBroker: newCommissionBrokerSliderValue,
            commissionCoordinator: newCommissionCoordinatorSliderValue || 0,
        });

        if (commissionBrokerRef.current && proposalRef.current) {
            commissionBrokerRef.current.value = numberFormat(newCommissionBrokerSliderValue);
            if (sliderChange) {
                proposalRef.current.value = numberFormat(newProposalSliderValue);
            }
        }
    };

    const handleComissionBrokerSliderChange = (value: string, sliderChange: boolean) => {
        if (!normalizedData) return;

        const newCommissionBrokerSliderValue = parseFloat(value);

        if (newCommissionBrokerSliderValue !== auxValues.commissionBroker) {
            setIsProposalButtonDisabled(false);
        } else {
            setIsProposalButtonDisabled(true);
        }

        const proportion =
            (newCommissionBrokerSliderValue - normalizedData.min_comission) /
            (normalizedData.max_comission - normalizedData.min_comission);

        const newProposalSliderValue =
            normalizedData.max_proposal -
            proportion * (normalizedData.max_proposal - normalizedData.min_proposal);

        const brokerProportion =
            (newCommissionBrokerSliderValue - brokerMin) / (brokerMax - brokerMin);

        let newCommissionCoordinatorSliderValue: number | undefined;
        if (coordMin > 0 && coordMax > 0) {
            newCommissionCoordinatorSliderValue =
                coordMin + brokerProportion * (coordMax - coordMin);
        }

        setSliderValues({
            proposal: newProposalSliderValue,
            commissionBroker: newCommissionBrokerSliderValue,
            commissionCoordinator: newCommissionCoordinatorSliderValue || 0,
        });

        if (proposalRef.current && commissionBrokerRef.current) {
            proposalRef.current.value = numberFormat(newProposalSliderValue);
            if (sliderChange) {
                commissionBrokerRef.current.value = numberFormat(newCommissionBrokerSliderValue);
            }
        }
    };

    const handleComissionCoordinatorSliderChange = (value: string, sliderChange: boolean) => {
        if (!normalizedData) return;

        const newComissionCoordinatorSliderValue = parseFloat(value);

        if (newComissionCoordinatorSliderValue !== auxValues.commissionCoordinator) {
            setIsProposalButtonDisabled(false);
        } else {
            setIsProposalButtonDisabled(true);
        }

        const coordinatorProportion =
            (newComissionCoordinatorSliderValue - coordMin) / (coordMax - coordMin);

        const newCommissionBrokerSliderValue =
            brokerMin + coordinatorProportion * (brokerMax - brokerMin);

        const proportion =
            (newCommissionBrokerSliderValue - normalizedData.min_comission) /
            (normalizedData.max_comission - normalizedData.min_comission);

        const newProposalSliderValue =
            normalizedData.max_proposal -
            proportion * (normalizedData.max_proposal - normalizedData.min_proposal);

        setSliderValues({
            proposal: newProposalSliderValue,
            commissionBroker: newCommissionBrokerSliderValue,
            commissionCoordinator: newComissionCoordinatorSliderValue,
        });

        if (
            proposalRef.current &&
            commissionBrokerRef.current &&
            commissionCoordinatorRef.current
        ) {
            proposalRef.current.value = numberFormat(newProposalSliderValue);
            commissionBrokerRef.current.value = numberFormat(newCommissionBrokerSliderValue);
            if (sliderChange) {
                commissionCoordinatorRef.current.value = numberFormat(
                    newComissionCoordinatorSliderValue,
                );
            }
        }
    };

    const changeInputValues = (inputField: TSliderInputField, value: string) => {
        if (!normalizedData) return;

        const rawValue = value
            .replace(/R\$\s*/g, '')
            .replaceAll('.', '')
            .replaceAll(',', '.');

        const numericalValue = parseFloat(rawValue);

        switch (inputField) {
            case 'proposal':
                if (
                    numericalValue >= normalizedData.min_proposal &&
                    numericalValue <= normalizedData.max_proposal &&
                    !isNaN(numericalValue) &&
                    numericalValue !== auxValues.proposal
                ) {
                    setIsProposalButtonDisabled(false);
                } else {
                    setIsProposalButtonDisabled(true);
                }

                if (
                    numericalValue < normalizedData.min_proposal ||
                    numericalValue > normalizedData.max_proposal ||
                    isNaN(numericalValue)
                ) {
                    setErrorMessage(true);
                    return;
                } else {
                    setErrorMessage(false);
                }

                setSliderValues((old) => ({
                    ...old,
                    proposal: numericalValue,
                }));
                handleProposalSliderChange(rawValue, false);
                break;

            case 'commissionBroker':
                if (
                    numericalValue >= normalizedData.min_comission &&
                    numericalValue <= normalizedData.max_comission &&
                    !isNaN(numericalValue) &&
                    numericalValue !== auxValues.commissionBroker
                ) {
                    setIsProposalButtonDisabled(false);
                } else {
                    setIsProposalButtonDisabled(true);
                }

                if (
                    numericalValue < normalizedData.min_comission ||
                    numericalValue > normalizedData.max_comission ||
                    isNaN(numericalValue)
                ) {
                    setErrorMessage(true);
                    return;
                } else {
                    setErrorMessage(false);
                }

                setSliderValues((old) => ({
                    ...old,
                    commissionBroker: numericalValue,
                }));
                handleComissionBrokerSliderChange(rawValue, false);
                break;

            case 'commissionCoordinator':
                if (
                    numericalValue >= normalizedData.valor_minimo_de_comissao_coordenador &&
                    numericalValue <= normalizedData.valor_maximo_de_comissao_coordenador &&
                    !isNaN(numericalValue) &&
                    numericalValue !== auxValues.commissionCoordinator
                ) {
                    setIsProposalButtonDisabled(false);
                } else {
                    setIsProposalButtonDisabled(true);
                }

                if (
                    numericalValue < normalizedData.valor_minimo_de_comissao_coordenador ||
                    numericalValue > normalizedData.valor_maximo_de_comissao_coordenador ||
                    isNaN(numericalValue)
                ) {
                    setErrorMessage(true);
                    return;
                } else {
                    setErrorMessage(false);
                }

                setSliderValues((old) => ({
                    ...old,
                    commissionCoordinator: numericalValue,
                }));
                handleComissionCoordinatorSliderChange(rawValue, false);
                break;

            default:
                break;
        }
    };

    const handleSaveProposalAndComission = async () => {
        if (!normalizedData) return;
        setSavingProposalAndComission(true);
        try {
            await saveProposalAndComission(normalizedData.proposta_id, sliderValues);

            sendToastMessage({
                title: 'Proposta e comissão salvas com sucesso!',
                type: 'success',
            });
            setIsProposalButtonDisabled(true);
            setAuxValues(sliderValues);
        } catch {
            sendToastMessage({
                title: 'Erro ao salvar proposta e comissão!',
                type: 'error',
            });
        }
        setSavingProposalAndComission(false);
    };

    const handleApplySuggestion = useCallback(() => {
        if (!normalizedData) return;

        const newValues = {
            proposal: Math.min(
                Math.max(suggestedProposal, normalizedData.min_proposal),
                normalizedData.max_proposal,
            ),
            commissionBroker: Math.min(
                Math.max(suggestedCommissions.broker, normalizedData.min_comission),
                normalizedData.max_comission,
            ),
            commissionCoordinator: Math.min(
                Math.max(
                    suggestedCommissions.coordinator,
                    normalizedData.valor_minimo_de_comissao_coordenador,
                ),
                normalizedData.valor_maximo_de_comissao_coordenador,
            ),
        };

        setSliderValues(newValues);
        setIsProposalButtonDisabled(
            newValues.proposal === auxValues.proposal &&
                newValues.commissionBroker === auxValues.commissionBroker &&
                newValues.commissionCoordinator === auxValues.commissionCoordinator,
        );

        if (proposalRef.current && commissionBrokerRef.current) {
            proposalRef.current.value = numberFormat(newValues.proposal);
            commissionBrokerRef.current.value = numberFormat(newValues.commissionBroker);
            if (commissionCoordinatorRef.current) {
                commissionCoordinatorRef.current.value = numberFormat(newValues.commissionCoordinator);
            }
        }
    }, [normalizedData, suggestedProposal, suggestedCommissions, auxValues]);

    const isAtSuggestion = useMemo(() => {
        return Math.abs(sliderValues.proposal - suggestedProposal) < PROPOSAL_MATCH_THRESHOLD;
    }, [sliderValues.proposal, suggestedProposal]);

    const isAtMin = useMemo(() => {
        return normalizedData
            ? Math.abs(sliderValues.proposal - normalizedData.min_proposal) < PROPOSAL_MATCH_THRESHOLD
            : false;
    }, [sliderValues.proposal, normalizedData]);

    const isAtMax = useMemo(() => {
        return normalizedData
            ? Math.abs(sliderValues.proposal - normalizedData.max_proposal) < PROPOSAL_MATCH_THRESHOLD
            : false;
    }, [sliderValues.proposal, normalizedData]);

    useEffect(() => {
        if (!normalizedData) return;

        const initialProposal = suggestions
            ? Math.min(
                  Math.max(suggestedProposal, normalizedData.min_proposal),
                  normalizedData.max_proposal,
              )
            : normalizedData.max_proposal;

        const initialCommission = suggestions
            ? Math.min(
                  Math.max(suggestedCommissions.broker, normalizedData.min_comission),
                  normalizedData.max_comission,
              )
            : normalizedData.min_comission;

        const brokerProportion =
            brokerMax > brokerMin ? (initialCommission - brokerMin) / (brokerMax - brokerMin) : 0;
        const initialCoordinator =
            suggestions && coordMin > 0 && coordMax > 0
                ? Math.min(
                      Math.max(
                          suggestedCommissions.coordinator,
                          normalizedData.valor_minimo_de_comissao_coordenador,
                      ),
                      normalizedData.valor_maximo_de_comissao_coordenador,
                  )
                : coordMin + brokerProportion * (coordMax - coordMin);

        setSliderValues({
            proposal: initialProposal,
            commissionBroker: initialCommission,
            commissionCoordinator: initialCoordinator,
        });

        setAuxValues({
            proposal: initialProposal,
            commissionBroker: initialCommission,
            commissionCoordinator: initialCoordinator,
        });

        if (proposalRef.current && commissionBrokerRef.current) {
            proposalRef.current.value = numberFormat(initialProposal);
            commissionBrokerRef.current.value = numberFormat(initialCommission);
            if (commissionCoordinatorRef.current) {
                commissionCoordinatorRef.current.value = numberFormat(initialCoordinator);
            }
        }
    }, [
        normalizedData,
        suggestions,
        suggestedProposal,
        suggestedCommissions,
        brokerMin,
        brokerMax,
        coordMin,
        coordMax,
    ]);

    const proposalProportionPct = useMemo(() => {
        if (!normalizedData) return 0;
        const range = normalizedData.max_proposal - normalizedData.min_proposal;
        if (range <= 0) return 0;
        return Math.round(
            Math.max(0, Math.min(PERCENTAGE_FACTOR, ((sliderValues.proposal - normalizedData.min_proposal) / range) * PERCENTAGE_FACTOR)),
        );
    }, [normalizedData, sliderValues.proposal]);

    if (!normalizedData) return null;

    return (
        <TooltipProvider delayDuration={TOOLTIP_DELAY_MS}>
            <div className="flex w-full flex-col gap-5">
                {/* Header com contexto SmartBlock */}
                <div className="flex flex-col gap-3 rounded-2xl border border-border/70 bg-card p-4 shadow-xs sm:p-5">
                    <div className="flex items-center gap-3">
                        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary/10 text-primary">
                            <BrainCircuit className="h-5 w-5" />
                        </div>
                        <div>
                            <div className="flex items-center gap-2">
                                <h2 className="font-nexa text-base font-extrabold uppercase tracking-wide text-foreground">
                                    Simulação de Proposta &amp; Comissão
                                </h2>
                            </div>
                            <p className="font-satoshi text-xs text-muted-foreground">
                                Ajuste proporcional calculado via motor de precificação SmartBlock
                            </p>
                        </div>
                    </div>

                    {/* Presets Rápidos */}
                    <div className="flex flex-wrap items-center gap-1.5 pt-1 border-t border-border/50">
                        <span className="text-[11px] font-semibold text-muted-foreground mr-1">
                            Atalhos:
                        </span>

                        {isLocalhost && (
                            <Tooltip>
                                <TooltipTrigger asChild>
                                    <button
                                        type="button"
                                        onClick={handleApplySuggestion}
                                        className={cn(
                                            'inline-flex items-center gap-1.5 rounded-lg border px-2.5 py-1 text-xs font-semibold transition-all cursor-pointer',
                                            isAtSuggestion
                                                ? 'border-amber-500/50 bg-amber-500/15 text-amber-700 dark:text-amber-400 font-bold shadow-xs'
                                                : 'border-border bg-background text-muted-foreground hover:bg-muted/60 hover:text-foreground',
                                        )}
                                    >
                                        <Sparkles className="h-3 w-3 text-amber-500" />
                                        Sugerido pelo SmartBlock
                                    </button>
                                </TooltipTrigger>
                                <TooltipContent side="top" sideOffset={6} className="pointer-events-none">
                                    <p className="text-xs">Aplica a proposta e comissão recomendadas pelo histórico de negociações aceitas.</p>
                                </TooltipContent>
                            </Tooltip>
                        )}

                        <button
                            type="button"
                            onClick={() => handleProposalSliderChange(normalizedData.min_proposal.toString(), true)}
                            className={cn(
                                'inline-flex items-center gap-1 rounded-lg border px-2.5 py-1 text-xs font-semibold transition-all cursor-pointer',
                                isAtMin
                                    ? 'border-primary/50 bg-primary/15 text-primary font-bold shadow-xs'
                                    : 'border-border bg-background text-muted-foreground hover:bg-muted/60 hover:text-foreground',
                            )}
                        >
                            Proposta mínima
                        </button>

                        <button
                            type="button"
                            onClick={() =>
                                handleProposalSliderChange(
                                    ((normalizedData.min_proposal + normalizedData.max_proposal) / 2).toString(),
                                    true,
                                )
                            }
                            className="inline-flex items-center gap-1 rounded-lg border border-border bg-background px-2.5 py-1 text-xs font-semibold text-muted-foreground hover:bg-muted/60 hover:text-foreground transition-all cursor-pointer"
                        >
                            <Scale className="h-3 w-3" />
                            Ponto Médio
                        </button>

                        <button
                            type="button"
                            onClick={() => handleProposalSliderChange(normalizedData.max_proposal.toString(), true)}
                            className={cn(
                                'inline-flex items-center gap-1 rounded-lg border px-2.5 py-1 text-xs font-semibold transition-all cursor-pointer',
                                isAtMax
                                    ? 'border-primary/50 bg-primary/15 text-primary font-bold shadow-xs'
                                    : 'border-border bg-background text-muted-foreground hover:bg-muted/60 hover:text-foreground',
                            )}
                        >
                            Proposta máxima
                        </button>
                    </div>
                </div>

                {/* Container dos Cards */}
                <div className="flex flex-col gap-4">
                    {/* Card 1: Proposta ao Credor (Desembolso) */}
                    <div className="flex flex-col gap-3 rounded-2xl border border-blue-500/20 bg-blue-500/[0.02] p-4.5 dark:bg-blue-950/20 shadow-xs">
                        <div className="flex items-center justify-between gap-3">
                            <div className="flex items-center gap-2.5">
                                <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-blue-500/10 text-blue-600 dark:text-blue-400">
                                    <Coins className="h-4 w-4" />
                                </div>
                                <div>
                                    <span className="text-xs font-bold text-foreground">
                                        Proposta ao Credor
                                    </span>
                                    <span className="block text-[10px] font-medium text-muted-foreground">
                                        Valor de desembolso líquido ao cedente
                                    </span>
                                </div>
                            </div>

                            <div className="flex items-center gap-1 rounded-xl border border-blue-300/60 bg-white px-3 py-1.5 shadow-xs focus-within:border-blue-500 focus-within:ring-2 focus-within:ring-blue-500/20 dark:border-blue-800/80 dark:bg-slate-900">
                                <span className="font-mono text-xs font-bold text-blue-600/70 dark:text-blue-400/70">
                                    R$
                                </span>
                                <input
                                    ref={proposalRef}
                                    type="text"
                                    onBlur={(e) => {
                                        e.target.value = formatCurrency(e.target.value);
                                    }}
                                    onChange={(e) => changeInputValues('proposal', e.target.value)}
                                    className="w-32 border-none bg-transparent p-0 text-right font-mono text-sm font-bold text-blue-700 outline-none focus:ring-0 dark:text-blue-300"
                                />
                            </div>
                        </div>

                        {/* Régua de Limites */}
                        <div className="flex items-center justify-between gap-2 text-[11px] font-mono font-medium text-muted-foreground">
                            <span>Min: {numberFormat(normalizedData.min_proposal)}</span>

                            {isLocalhost && (
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <button
                                            type="button"
                                            onClick={handleApplySuggestion}
                                            className="inline-flex items-center gap-1 rounded-full border border-amber-500/30 bg-amber-500/10 px-2.5 py-0.5 text-[10px] font-bold font-mono text-amber-600 dark:text-amber-400 hover:bg-amber-500/20 transition-all cursor-pointer"
                                        >
                                            <Sparkles className="h-2.5 w-2.5" />
                                            Sugerido: {numberFormat(suggestedProposal)}
                                        </button>
                                    </TooltipTrigger>
                                    <TooltipContent side="top" sideOffset={6} className="pointer-events-none">
                                        <p className="text-xs">Sugestão calculada com base no histórico de conversão deste perfil de ativo.</p>
                                    </TooltipContent>
                                </Tooltip>
                            )}

                            <span>Máx: {numberFormat(normalizedData.max_proposal)}</span>
                        </div>

                        {/* Slider */}
                        <div className="relative w-full py-1">
                            <input
                                type="range"
                                step={SLIDER_STEP}
                                min={normalizedData.min_proposal}
                                max={normalizedData.max_proposal}
                                value={sliderValues.proposal}
                                onChange={(e) => handleProposalSliderChange(e.target.value, true)}
                                className="range-slider w-full cursor-pointer"
                            />
                            {isLocalhost && (
                                <div
                                    className="absolute top-1/2 h-5 w-[2px] -translate-y-1/2 -translate-x-1/2 rounded-full bg-emerald-500 shadow-xs pointer-events-none z-10"
                                    style={{ left: getSliderThumbOffsetStyle(proposalSuggestionPct) }}
                                />
                            )}
                        </div>
                    </div>

                    {/* Card 2: Comissão da Operação (Broker) */}
                    <div className="flex flex-col gap-3 rounded-2xl border border-emerald-500/20 bg-emerald-500/[0.02] p-4.5 dark:bg-emerald-950/20 shadow-xs">
                        <div className="flex items-center justify-between gap-3">
                            <div className="flex items-center gap-2.5">
                                <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
                                    <Percent className="h-4 w-4" />
                                </div>
                                <div>
                                    <span className="text-xs font-bold text-foreground">
                                        Comissão da Operação
                                    </span>
                                    <span className="block text-[10px] font-medium text-muted-foreground">
                                        Honorários comerciais da corretagem
                                    </span>
                                </div>
                            </div>

                            <div className="flex items-center gap-1 rounded-xl border border-emerald-300/60 bg-white px-3 py-1.5 shadow-xs focus-within:border-emerald-500 focus-within:ring-2 focus-within:ring-emerald-500/20 dark:border-emerald-800/80 dark:bg-slate-900">
                                <span className="font-mono text-xs font-bold text-emerald-600/70 dark:text-emerald-400/70">
                                    R$
                                </span>
                                <input
                                    ref={commissionBrokerRef}
                                    type="text"
                                    onBlur={(e) => {
                                        e.target.value = formatCurrency(e.target.value);
                                    }}
                                    onChange={(e) => changeInputValues('commissionBroker', e.target.value)}
                                    className="w-32 border-none bg-transparent p-0 text-right font-mono text-sm font-bold text-emerald-700 outline-none focus:ring-0 dark:text-emerald-300"
                                />
                            </div>
                        </div>

                        {/* Régua de Limites */}
                        <div className="flex items-center justify-between gap-2 text-[11px] font-mono font-medium text-muted-foreground">
                            <span>Min: {numberFormat(normalizedData.min_comission)}</span>

                            {isLocalhost && (
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <button
                                            type="button"
                                            onClick={handleApplySuggestion}
                                            className="inline-flex items-center gap-1 rounded-full border border-amber-500/30 bg-amber-500/10 px-2.5 py-0.5 text-[10px] font-bold font-mono text-amber-600 dark:text-amber-400 hover:bg-amber-500/20 transition-all cursor-pointer"
                                        >
                                            <Sparkles className="h-2.5 w-2.5" />
                                            Sugerido: {numberFormat(suggestedCommissions.broker)}
                                        </button>
                                    </TooltipTrigger>
                                    <TooltipContent side="top" sideOffset={6} className="pointer-events-none">
                                        <p className="text-xs">Comissão proporcional correspondente à proposta sugerida.</p>
                                    </TooltipContent>
                                </Tooltip>
                            )}

                            <span>Máx: {numberFormat(normalizedData.max_comission)}</span>
                        </div>

                        {/* Slider */}
                        <div className="relative w-full py-1">
                            <input
                                type="range"
                                step={SLIDER_STEP}
                                min={normalizedData.min_comission}
                                max={normalizedData.max_comission}
                                value={sliderValues.commissionBroker}
                                onChange={(e) => handleComissionBrokerSliderChange(e.target.value, true)}
                                className="range-slider-reverse w-full cursor-pointer"
                            />
                            {isLocalhost && (
                                <div
                                    className="absolute top-1/2 h-5 w-[2px] -translate-y-1/2 -translate-x-1/2 rounded-full bg-emerald-500 shadow-xs pointer-events-none z-10"
                                    style={{ left: getSliderThumbOffsetStyle(commissionSuggestionPct) }}
                                />
                            )}
                        </div>
                    </div>
                </div>

                {/* Resumo Consolidado com Dinâmica Operacional */}
                <div className="flex flex-col gap-2 rounded-xl border border-border/70 bg-muted/20 p-3.5 text-xs">
                    <div className="flex items-center justify-between border-b border-border/40 pb-2">
                        <span className="text-[11px] font-bold text-foreground">
                            Resumo da Operação
                        </span>
                        <span className="font-mono text-[11px] text-muted-foreground font-semibold">
                            Posição na Faixa: {proposalProportionPct}%
                        </span>
                    </div>

                    <div className="grid grid-cols-2 gap-3 pt-1">
                        <div>
                            <span className="text-[10px] font-medium text-muted-foreground block">
                                Desembolso ao Credor:
                            </span>
                            <span className="font-mono text-sm font-bold text-blue-600 dark:text-blue-400">
                                {numberFormat(sliderValues.proposal)}
                            </span>
                        </div>
                        <div className="text-right">
                            <span className="text-[10px] font-medium text-muted-foreground block">
                                Comissão Broker:
                            </span>
                            <span className="font-mono text-sm font-bold text-emerald-600 dark:text-emerald-400">
                                {numberFormat(sliderValues.commissionBroker)}
                            </span>
                        </div>
                    </div>
                </div>

                {/* Alerta de erro */}
                {errorMessage && (
                    <div className="flex items-center justify-center gap-2 rounded-xl border border-destructive/30 bg-destructive/10 p-3 text-xs font-semibold text-destructive">
                        <AlertCircle className="h-4 w-4 shrink-0" />
                        <span>
                            Valor fora do intervalo permitido para este ativo (entre{' '}
                            {numberFormat(normalizedData.min_proposal)} e{' '}
                            {numberFormat(normalizedData.max_proposal)}).
                        </span>
                    </div>
                )}

                {/* Botão de Salvar */}
                {normalizedData?.proposta_id && (
                    <Button
                        disabled={isProposalButtonDisabled || savingProposalAndComission}
                        onClick={handleSaveProposalAndComission}
                        className="h-11 w-full rounded-xl bg-primary font-satoshi text-sm font-semibold text-white shadow-sm hover:bg-primary/90 active:scale-[0.99] transition-all disabled:cursor-not-allowed disabled:opacity-50 flex items-center justify-center gap-2"
                    >
                        {savingProposalAndComission ? (
                            <>
                                <span>Salvando dados...</span>
                                <Loader2 className="h-4 w-4 animate-spin" />
                            </>
                        ) : (
                            <>
                                <Save className="h-4 w-4" />
                                <span>Salvar Proposta e Comissão</span>
                            </>
                        )}
                    </Button>
                )}
            </div>
        </TooltipProvider>
    );
};

export default LeadMagnetSlider;

