                                    <div className="flex items-center gap-1 rounded-xl border border-emerald-300/60 bg-white px-3 py-1.5 shadow-xs focus-within:border-emerald-500 focus-within:ring-2 focus-within:ring-emerald-500/20 dark:border-emerald-800/80 dark:bg-slate-900">
                                        <span className="font-mono text-xs font-bold text-emerald-600/70 dark:text-emerald-400/70">
                                            R$
                                        </span>
                                        <input
                                            ref={commissionBrokerRef}
                                            type="text"
                                            onBlur={(e) => {
                                                e.target.value = formatCurrency(e.target.value);
                                            }}
