                                                changeInputValues('commissionBroker', e.target.value)
                                            }
                                            className="w-32 border-none bg-transparent p-0 text-right font-mono text-sm font-bold text-emerald-700 outline-none focus:ring-0 dark:text-emerald-300"
                                        />
                                    </div>
                                </div>
                                <div className="flex w-full items-center justify-between gap-2 text-xs font-medium text-paragraph font-mono">
                                    <span>Min: {numberFormat(commissionSliderBounds.min || 0)}</span>
                                    {isLocalhost && suggestedBrokerCommission > 0 && commissionSliderBounds.max > commissionSliderBounds.min && (
                                        <Tooltip>
                                            <TooltipTrigger asChild>
                                                <button
                                                    type="button"
                                                    onClick={() => handleProposalSliderChange(suggestedProposal.toString(), true)}
                                                    className="inline-flex items-center gap-1 rounded-full border border-amber-500/30 bg-amber-500/10 px-2 py-0.5 text-[10px] font-bold font-mono text-amber-600 dark:text-amber-400 hover:bg-amber-500/20 transition-all cursor-pointer"
                                                >
                                                    <Sparkles className="h-2.5 w-2.5" />
                                                    Sugerido: {numberFormat(suggestedBrokerCommission)}
                                                </button>
                                            </TooltipTrigger>
                                            <TooltipContent side="top" sideOffset={6} className="pointer-events-none">
                                                <p className="text-xs">Comissão proporcional correspondente à proposta sugerida.</p>
                                            </TooltipContent>
                                        </Tooltip>
                                    )}
                                    <span>Máx: {numberFormat(commissionSliderBounds.max || 0)}</span>
                                </div>
                                <div className="relative w-full py-1">
                                    <input
                                        type="range"
                                        step={SLIDER_STEP}
                                        min={commissionSliderBounds.min || 0}
                                        max={commissionSliderBounds.max || 0}
                                        value={sliderValues.commissionBroker}
                                        onChange={(e) =>
                                            handleComissionBrokerSliderChange(e.target.value, true)
                                        }
                                        className="range-slider-reverse w-full cursor-pointer"
                                    />
                                    {isLocalhost && suggestedBrokerCommission > 0 && commissionSliderBounds.max > commissionSliderBounds.min && (
                                        <div
                                            className="absolute top-1/2 h-5 w-[2px] -translate-y-1/2 -translate-x-1/2 rounded-full bg-emerald-500 shadow-xs pointer-events-none z-10"
                                            style={{ left: getSliderThumbOffsetStyle(commissionSuggestionPct) }}
                                        />
                                    )}
                                </div>
                            </div>
                        </div>
                        {errorMessage && (
                            <p className="absolute -bottom-2 w-full text-center text-xs font-medium text-red">
                                Valor&#40;res&#41; fora do escopo definido
                            </p>
                        )}
                    </div>

                    <div className="flex gap-2">
                        <Button
                            variant="outline-default"
                            disabled={
                                isSemSmartblock ||
                                isProposalButtonDisabled.current ||
                                savingProposalAndComission ||
                                isSaveButtonDisabled
                            }
                            isLoading={savingProposalAndComission}
                            onClick={handleProposalAndCommission}
                            className="h-8 w-full rounded-[40px] border border-blue-200 bg-background px-2 text-sm font-medium text-blue-600 transition-all duration-300 hover:bg-blue-50 disabled:cursor-not-allowed disabled:opacity-50"
                        >
                            {'Salvar Oferta'}
                        </Button>
                        <div className="w-full">
                            <BrokerProposalWizard
                                extratoId={extratoId}
                                brandKitOwnerUserId={brandKitOwnerUserId}
                                buttonLabel="Gerar Proposta"
                                buttonClassName="!h-8 w-full px-2"
                                buttonDisabled={!maxProposal || isSemSmartblock}
                                offerValue={sliderValues.proposal}
                                offerCommission={sliderValues.commissionBroker}
                                onOfferChange={(value) => {
                                    if (proposalRef.current) {
                                        proposalRef.current.value = numberFormat(value);
                                    }
                                    handleProposalSliderChange(String(value), true);
                                }}
                            />
                        </div>
                    </div>
                    </div>
                </div>
            </div>
        </div>
        </TooltipProvider>
    );
};

export default BrokerSlider;

