'use client';

import { useState } from 'react';
import BrokerSlider from '@/components/Sliders/BrokerSlider';
import { useBrokerStore } from '@/store/useBroker';

interface ChatLeadMagnetSliderWrapperProps {
    contextExtratoId?: string;
    initialProposal?: number;
    initialCommission?: number;
    propostaMinima?: number;
    propostaMaxima?: number;
    comissaoMinima?: number;
    comissaoMaxima?: number;
}

function formatBrl(value: number): string {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
}

function lerp(a: number, b: number, t: number): number {
    return a + (b - a) * t;
}

interface InlineRangeSliderProps {
    minProposta: number;
    maxProposta: number;
    minComissao?: number;
    maxComissao?: number;
}

function InlineRangeSlider({ minProposta, maxProposta, minComissao, maxComissao }: InlineRangeSliderProps) {
    const [sliderPct, setSliderPct] = useState(0);

    const proposalValue = lerp(minProposta, maxProposta, sliderPct);
    // Comissão é inversamente proporcional: proposta máxima → comissão mínima
    const commissionValue =
        minComissao != null && maxComissao != null
            ? lerp(maxComissao, minComissao, sliderPct)
            : null;

    return (
        <div className="w-full rounded-xl border border-border/60 bg-card p-4 space-y-4">
            <div className="flex items-center justify-between">
                <span className="text-[11px] font-bold tracking-[0.15em] uppercase text-muted-foreground">
                    Simulador de Proposta
                </span>
                <span className="text-[10px] text-muted-foreground/60 bg-muted px-2 py-0.5 rounded-full">
                    SmartBlock
                </span>
            </div>

            <div className="space-y-1">
                <div className="flex justify-between text-[11px] text-muted-foreground">
                    <span>{formatBrl(minProposta)}</span>
                    <span>{formatBrl(maxProposta)}</span>
                </div>
                <input
                    type="range"
                    min={0}
                    max={100}
                    value={Math.round(sliderPct * 100)}
                    onChange={(e) => setSliderPct(Number(e.target.value) / 100)}
                    className="w-full accent-blue-500 cursor-pointer"
                />
            </div>

            <div className="grid grid-cols-2 gap-3">
                <div className="rounded-lg bg-muted/50 border border-border/50 px-3 py-2.5">
                    <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground mb-1">
                        Proposta
                    </p>
                    <p className="text-[15px] font-bold text-foreground font-mono">
                        {formatBrl(proposalValue)}
                    </p>
                </div>
                {commissionValue != null && (
                    <div className="rounded-lg bg-muted/50 border border-border/50 px-3 py-2.5">
                        <p className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground mb-1">
                            Comissão
                        </p>
                        <p className="text-[15px] font-bold text-blue-600 dark:text-blue-400 font-mono">
                            {formatBrl(commissionValue)}
                        </p>
                    </div>
                )}
            </div>

            <p className="text-[10px] text-muted-foreground/50">
                Valores baseados em nossa precificação inteligente
                .
            </p>
        </div>
    );
}

export function ChatLeadMagnetSliderWrapper({
    contextExtratoId,
    initialProposal,
    initialCommission,
    propostaMinima,
    propostaMaxima,
    comissaoMinima,
    comissaoMaxima,
}: ChatLeadMagnetSliderWrapperProps) {
    const storeExtratoId = useBrokerStore((store) => store.extratoId);
    // Prioriza o ofício ativo da tela para evitar simulação em ID stale do chat.
    const extratoId = storeExtratoId || contextExtratoId;

    if (!extratoId) {
        if (propostaMinima != null && propostaMaxima != null && propostaMaxima > propostaMinima) {
            return (
                <InlineRangeSlider
                    minProposta={propostaMinima}
                    maxProposta={propostaMaxima}
                    minComissao={comissaoMinima}
                    maxComissao={comissaoMaxima}
                />
            );
        }

        return null;
    }

    return (
        <div className="w-full">
            <BrokerSlider
                overrideExtratoId={extratoId}
                initialProposalValue={initialProposal}
                initialCommissionValue={initialCommission}
            />
        </div>
    );
}

