// ==================
const { data } = useUserInfoStore();

// ==================
// # Contexts
// ==================
const { setModalOpen } = useContext(DefaultLayoutContext);

// ==================
// # States
// ==================
const [fullScreen, setFullScreen] = useState<boolean>(false);
const [loading, setLoading] = useState<boolean>(false);
const [backendResponse, setBackendResponse] = useState<LeadMagnetResposeProps | null>(null);
const [errorMessage, setErrorMessage] = useState<string | null>(null);
const [negociacaoBloqueada, setNegociacaoBloqueada] = useState<boolean>(false);
const [blockingInfo, setBlockingInfo] = useState<BlockingInfo | null>(null);
const [precificacaoPanelFeedback, setPrecificacaoPanelFeedback] =
    useState<SmartblockPrecificacaoFeedback | null>(null);
const [showResults, setShowResults] = useState<boolean>(false);

// ==================
// # Constants
// ==================
const isCalcFormCalculateButtonOutage =
    process.env.NEXT_PUBLIC_FF_OUTAGE_CALC_FORM_CALCULATE_BUTTON === 'true';

// ==================
// # Refs
// ==================
const modalRef = useRef<HTMLDivElement | null>(null);
const resultContainerRef = useRef<HTMLDivElement | null>(null);
const scrollContainerRef = useRef<HTMLDivElement | null>(null);

// ==================
// # Form
// ==================
const form = useCalculadoraForm({
    validation: 'create',
    defaultValues: {
        esfera: undefined,
        ente_devedor: 'UNIÃO FEDERAL',
        tipo_do_oficio: 'PRECATÓRIO',
        numero_de_meses: 0,
        gerar_cvld: true,
        especie: 'Principal',
        base_calculo_rra: CalculatorEnum.PRINCIPAL,
        imposto_de_renda_percentual: '0.0300',
        contribuicao_previdenciaria_tipo: CalculatorEnum.PERCENTUAL,
        honorarios_tipo: CalculatorEnum.PERCENTUAL,
        imposto_de_renda_tipo: CalculatorEnum.PERCENTUAL,
    },
});

const watchedForContext = form.watch([
    'esfera',
    'natureza',
    'tipo_do_oficio',
    'regime',
    'ente_devedor',
    'tribunal',
    'estado_ente_devedor',
    'data_base',
    'data_requisicao',
    'valor_principal',
    'valor_juros',
    'incidencia_ir',
    'incidencia_rra',
    'incidencia_pss',
    'incide_contribuicao_previdenciaria',
    'percentual_de_honorarios',
    'tem_deducoes',
    'deducoes',
    'deposito_parcial',
    'valor_aquisicao_total',
    'ja_possui_destacamento',
]);

const newFormSurface = useMemo<PageSurfaceRegistration>(() => {
    const values = form.getValues();
    const signals = calculatorSignalsToRecord(
        buildCalculatorFormSignals(values as Record<string, unknown>, {
            entryFromOcr: Boolean(docData),
        }),
    );
    return {
        surfaceId: 'calculator:new-form',
        surfaceKind: 'calculator',
        stage: showResults ? 'result' : 'form',
        priority: 'modal',
        label: 'Calculadora',
        mode: leadId ? 'operational' : 'conceptual',
        anchors: {
            ...(leadId ? { leadId } : {}),
        },
        signals,
        capabilities: [
            'generate-proposal',
            'review-ir-pss',
            'review-form',
            'crosscheck-fiscal',
            'crosscheck-classification',
        ],
        helpTopics: [
            'como-calcular-precatorio',
            'gerar-proposta',
            'rra-meses',
            'ente-esfera',
        ],
        selectableBlocks: [
            { id: 'form-errors', label: 'Erros do formulário' },
            { id: 'form-required', label: 'Campos obrigatórios' },
            { id: 'form-fiscal', label: 'Flags fiscais (IR/RRA/PSS)' },
            { id: 'form-classification', label: 'Classificação do ofício' },
        ],
        sensitivity: 'internal',
    };
    // watchedForContext keeps signals fresh when form fields change
    // eslint-disable-next-line react-hooks/exhaustive-deps
}, [leadId, docData, showResults, watchedForContext]);
useRegisterPageSurface(newFormSurface);

// ==================
// # Functions
// ==================
const resetSubmissionFeedback = () => {
    setErrorMessage(null);
    setNegociacaoBloqueada(false);
    setBlockingInfo(null);
    setPrecificacaoPanelFeedback(null);
    setBackendResponse(null);
};

const onSubmit = async (formData: any) => {
    setLoading(true);
    resetSubmissionFeedback();

    // ============================================
    // verifica data base para enviar toast (provisório)
    // ============================================
    if (formData.data_base < '2001-01-01') {
        sendToastMessage({
            title: 'Atenção',
            description:
                'A data base informada é anterior a 01/01/2001. A atualização de valores para datas bases anteriores a esta está indisponível no momento.',
            type: 'warning',
        });
        throw new Error('Data base anterior a 2001-01-01');
    }

    if (formData.gerar_cvld) {
        if (!isCPFOrCNPJValid(form.watch('cpf_cnpj') || '')) {
            sendToastMessage({
                title: 'CPF ou CNPJ inválido',
                description:
                    'O CPF ou CNPJ inserido é inválido. Preencha corretamente e tente novamente.',
                type: 'error',
            });
            throw new Error('CPF ou CNPJ inválido');
        }
    }

    if (leadId) {
        // fazer scroll suave para a área de resultados
        scrollToTop();
    }

    if (formData.tribunal === 'TRF1' || formData.tribunal === 'TRF6') {
        formData.nao_incide_selic_no_periodo_db_ate_abril = true;
    } else {
        if (formData.data_base < '2021-12-01') {
            formData.nao_incide_selic_no_periodo_db_ate_abril = false;
        }
    }

    if (!formData.regime) {
        formData.regime = 'GERAL';
    }

    if (formData.data_base > '2021-12-01') {
        formData.incidencia_juros_moratorios = false;
    }

    formData = processFormData(formData);

    const url = formData.gerar_cvld ? '/api/lead-magnet/save/' : '/api/lead-magnet/';

    try {
        const response = await generateProposalCalculation(url, formData);

        if (response.status === 201) {
            sendToastMessage({
                title: 'Dados salvos no Celer com sucesso!',
                type: 'success',
            });
        }

        if (isSmartblockPrecificacaoIssue(response)) {
            const warningMessage =
                extractPrecificacaoMessage(response) ??
                'Esse ofício não possui regra ativa para os critérios informados.';
            const feedback = buildSmartblockPrecificacaoFeedback(
                warningMessage,
                extractSemSmartblockReason(response),
            );
            setPrecificacaoPanelFeedback(feedback);
            setErrorMessage(feedback.description);
            sendToastMessage({
                ...feedback,
                clickAction:
                    feedback.actionlabel === 'Abrir chamado'
                        ? () => useSupportModalStore.getState().openModal()
                        : undefined,
            });
        } else {
            setPrecificacaoPanelFeedback(null);
        }
        setBlockingInfo(null);
        setBackendResponse(response);
        setShowResults(true);
        if (leadId) {
            await sleep(TOAST_INTERVAL_AWAIT_PROMISE);
            sendToastMessage({
                type: 'loading',
                title: 'Vinculando ofício ao lead...',
            });
            await vinculateOficioToLead(response.extrato_id, leadId);
            sendToastMessage({
                type: 'success',
                title: 'Ofício vinculado ao lead com sucesso!',
            });
        }

        // invalida queries relacionadas a extratos e propostas
        queryClient.invalidateQueries({ queryKey: [QueryKeys.oficios.list], type: 'all' });
        queryClient.invalidateQueries({
            queryKey: [QueryKeys.broker.dashboardTable],
            type: 'all',
        });
    } catch (error) {
        if (error instanceof AxiosError && error.response?.data) {
            console.error(error);
            const errorData = error.response.data as Record<string, unknown>;
            let message = getUserFacingApiMessage(
                error,
                'Ocorreu um erro ao processar sua solicitação.',
            );

            // Verificar se é um erro de bloqueio com blocking_info
            if (errorData.blocking_info) {
                const nextBlockingInfo: BlockingInfo = errorData.blocking_info as BlockingInfo;
                setBlockingInfo(nextBlockingInfo);
                setPrecificacaoPanelFeedback(null);
                setErrorMessage(nextBlockingInfo.mensagem);

                sendToastMessage({
                    title: 'Precatório já adquirido',
                    description: buildBlockingArchiveDescription(nextBlockingInfo),
                    type: 'error',
                    actionlabel: 'Abrir chamado',
                    clickAction: () => useSupportModalStore.getState().openModal(),
                });
                setShowResults(true);
            } else if (
                (errorData.result as Record<string, unknown> | undefined)
                    ?.negociacao_bloqueada ||
                errorData.negociacao_bloqueada
            ) {
                const resultPayload = errorData.result as
                    | Record<string, unknown>
                    | undefined;
                const mensagemBloqueio =
                    (typeof resultPayload?.smart_block_mensagem === 'string' &&
                        resultPayload.smart_block_mensagem) ||
                    message;

                setBlockingInfo(null);
                setPrecificacaoPanelFeedback(null);
                setNegociacaoBloqueada(true);
                setErrorMessage(mensagemBloqueio);
                setShowResults(true);
                sendToastMessage({
                    title: 'Perfil fora da política de negociação',
                    description: mensagemBloqueio,
                    type: 'warning',
                });
            } else {
                setBlockingInfo(null);
                const isSmartBlockError = isSmartblockPrecificacaoIssue(errorData);
                if (isSmartBlockError) {
                    message =
                        extractPrecificacaoMessage(errorData) ??
                        'Atenção: No momento, não negociamos precatórios nesse perfil. Entre em contato conosco para maiores esclarecimentos.';
                }
                if (isSmartBlockError) {
                    const feedback = buildSmartblockPrecificacaoFeedback(
                        message,
                        extractSemSmartblockReason(errorData),
                    );
                    setPrecificacaoPanelFeedback(feedback);

