import { useTopNotchClipPath } from '@/hooks/useTopNotchClipPath';
import { cn } from '@/lib/utils';
import { getCedenteData, getLinkedCedenteEsteiras } from '@/services/BrokerServices';
import { useBrokerStore } from '@/store/useBroker';
