    const topNotchRef = useRef<HTMLDivElement>(null);
    useTopNotchClipPath({ notchRef: topNotchRef });

    // Start extrato fetch as soon as tabs mount (before child trees settle).
    useQuery(useExtratoDataQueryOptions(id));

    const { data: linkedCedentesList } = useQuery(createOficioLinkedCedentesOptions(id));

    const filteredLinkedCedentesList = useMemo(
        () => filterVisibleCedenteLinks(linkedCedentesList),
        [linkedCedentesList],
    );

    async function prefetchCedenteData(cedenteId: string) {
        queryClient.prefetchQuery({
            queryKey: [QueryKeys.cedentes.data, cedenteId],
            queryFn: () => getCedenteData(cedenteId),
        });
        queryClient.prefetchQuery({
            queryKey: [QueryKeys.cedentes.linkedEsteirasCedente, cedenteId],
            queryFn: () => getLinkedCedenteEsteiras(cedenteId),
        });
    }

    const setExtratoId = useBrokerStore((store) => store.setExtratoId);

    const [prevId, setPrevId] = useState<string | null>(null);
    if (id !== prevId) {
        setPrevId(id);
        setExtratoId(id);
    }

    useEffect(() => {
        posthog.capture('crm_broker_details_tab_changed', {
            extrato_id: id,
            tab: activeTab,
        });
