export type NewFormResultViewState = {
    loading: boolean;
    showResults: boolean;
    errorMessage: string | null;
};

export type NewFormResultView = 'loading' | 'placeholder' | 'error' | 'success';

export function resolveNewFormResultView(state: NewFormResultViewState): NewFormResultView {
    if (state.loading) return 'loading';
    if (!state.showResults) return 'placeholder';
    if (state.errorMessage) return 'error';
    return 'success';
}

