'use client';

import { ErrorMessageBox } from '@/components/ErrorMessage/ErrorMessageBox';
import { LeadsTableSkeleton } from '@/components/Skeletons/LeadsTableSkeleton';
import { Button } from '@/components/ui/button';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { QueryKeys } from '@/constants/query-keys';
import { useGetLeadsByStatusAndSituationQuery } from '@/hooks/queries/leads';
import { cn } from '@/lib/utils';
import { deleteLead, getLeadById, getLeadsByStatus } from '@/services/leads';
import { Filter as FilterType } from '@/types/filter';
import queryClient from '@/utils/queryClient';
import {
    flexRender,
    getCoreRowModel,
    getFilteredRowModel,
    getPaginationRowModel,
    getSortedRowModel,
    useReactTable,
    type ColumnFiltersState,
    type SortingState,
    type VisibilityState,
} from '@tanstack/react-table';
import { ChevronDown, ChevronLeft, ChevronRight, ChevronUp, List, X } from 'lucide-react';
import { m } from 'motion/react';
import { useEffect, useMemo, useState } from 'react';
import { LeadTableFilter } from '../Filters/LeadTableFilter';

import { CreateLeadModal } from '@/components/Modals/CreateLeadModal';
import { useLeadTasksTableContext } from '@/context/LeadTasksTableContext';
import { LeadStatus } from '@/enums/leadStatus.enum';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { GetLeadByIdResponse, GetLeadsResponse, Lead } from '@/interfaces/ILead';
import { useMutation } from '@tanstack/react-query';
import { LeadSheetInfo } from '../LeadSheet/lead-sheet-info';
import { DesignateResponsableModal } from '../LeadSheet/modal/designate-responsable-modal';
import { generateColumns } from './Columns/TaskTableColumns';

interface LeadFrioTableProps {
    title: string;
    selectedStatus: string;
    currentSituation: string;
    tableColors?: {
        bg: string;
        border: string;
        text: string;
    };
}

export function LeadTable({
    title,
    tableColors,
    selectedStatus,
    currentSituation,
}: LeadFrioTableProps) {
    const [isOpen, setIsOpen] = useState<string | null>(currentSituation);
    const [sorting, setSorting] = useState<SortingState>([]);
    const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
    const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({});
    const [rowSelection, setRowSelection] = useState({});
    const [currentPage, setCurrentPage] = useState(1);
    const [selectedLeadId, setSelectedLeadId] = useState<string | undefined>(undefined);
    const [selectedLead, setSelectedLead] = useState<GetLeadByIdResponse | undefined>(undefined);
    const [selectedLeadForDesignateResponsable, setSelectedLeadForDesignateResponsable] = useState<
        GetLeadByIdResponse | undefined
    >(undefined);
    const [filters, setFilters] = useState<FilterType[]>([
        {
            id: 'status',
            label: 'Status',
            value: selectedStatus,
        },
        {
            id: 'situacao',
            label: 'Situação',
            value: currentSituation,
        },
        {
            id: 'origem',
            label: 'Origem',
            value: undefined,
        },
        {
            id: 'tentativas',
            label: 'Tentativas de contato',
            value: undefined,
        },
        {
            id: 'ultimo_contato',
            label: 'Dias sem contato',
            value: undefined,
        },
        {
            id: 'prazo_final',
            label: 'Prazo final',
            value: undefined,
        },
    ]);

    const {
        data: leads,
        isLoading: isLoadingLeads,
        isRefetching: isRefetchingLeads,
        isError: isErrorLeads,
        refetch: refetchLeads,
    } = useGetLeadsByStatusAndSituationQuery(filters, currentPage);

    const {
        setNewFormModalConfig
    } = useLeadTasksTableContext();

    const deleteLeadMutation = useMutation({
        mutationFn: (leadId: string) => deleteLead(leadId),

        onSuccess: (_, leadId) => {
            sendToastMessage({
                title: 'Lead excluído com sucesso',
                type: 'success',
            });
            queryClient.invalidateQueries({ queryKey: [QueryKeys.leads.listByStatus] });
            queryClient.invalidateQueries({ queryKey: [QueryKeys.leads.kanban] });
            queryClient.invalidateQueries({ queryKey: [QueryKeys.leads.calendar] });
            queryClient.setQueryData<GetLeadsResponse>(
                [QueryKeys.leads.listByStatus, filters, currentPage],
                (old) => {
                    if (!old) return old;
                    return {
                        ...old,
                        results: old.results.filter((lead: Lead) => lead.leadId !== leadId),
                        count: old.count - 1,
                    };
                },
            );
        },

        onError: () => {
            sendToastMessage({
                title: 'Erro ao excluir lead',
                type: 'error',
            });
        },
    });

