import { WorkflowModal } from '@/components/Modals/Leads/WorkflowModal';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Separator } from '@/components/ui/separator';
import {
    Sheet,
    SheetClose,
    SheetContent,
    SheetDescription,
    SheetHeader,
    SheetOverlay,
    SheetTitle,
} from '@/components/ui/sheet';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { QueryKeys } from '@/constants/query-keys';
import { ROLES } from '@/constants/roles';
import { useLeadTasksTableContext } from '@/context/LeadTasksTableContext';
import { LeadStatus } from '@/enums/leadStatus.enum';
import { capitalizeWords } from '@/functions/formaters/capitalizeWords';
import { dicebearSvgUrl } from '@/functions/dicebearSeed';
import dateFormater from '@/functions/formaters/dateFormater';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { GetLeadByIdResponse } from '@/interfaces/ILead';
import { cn } from '@/lib/utils';
import { deleteLead, getLeadById, getLeadsHistory } from '@/services/leads';
import { useConverterLeadParaCedenteMutation } from '@/hooks/mutations/leads';
import { CelerRoles, useUserInfoStore } from '@/store/userInfo';
import { useBrokerStore } from '@/store/useBroker';
import queryClient from '@/utils/queryClient';
import { useMutation, useQuery } from '@tanstack/react-query';
import {
    ArrowLeftRight,
    ArrowRightToLine,
    Building2,
    Calendar,
    CalendarCheck,
    CalendarClock,
    CalendarSync,
    ChevronRight,
    ClockAlert,
    DollarSign,
    FileClock,
    FileText,
    IdCard,
    LayoutGrid,
    Loader,
    LucideIcon,
    MapPin,
    MessageSquare,
    PackageOpen,
    Sheet as SheetIcon,
    Tags,
    Trash,
    User,
    UserPen,
    X,
} from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { InfoItemExtrato } from '../info-item-extrato';
import { InfoItemLead } from '../info-item-lead';
import { SheetInfoHistory } from '../sheet-info-history';
import { LeadAiMemoryTab } from './LeadAiMemoryTab';
import { LeadSheetSkeleton } from './Lead-sheet-skeleton';
import { SheetContactTab } from './sheet-contact-tab';

interface LeadSheetInfoProps {
    leadId: string;
    setSelectedLeadForDesignateResponsable: (lead: GetLeadByIdResponse) => void;
    onOpenNewForm?: () => void;
    onClose: () => void;
    setSelectedLead?: (lead: GetLeadByIdResponse) => void;
    currentSituation?: string;
    tableColors?: {
        bg: string;
        border: string;
        text: string;
    };
    fromCalendar?: boolean;
}

type FieldType = 'text' | 'date' | 'currency' | 'cpfCnpj';

interface LeadFieldConfig {
    key: keyof GetLeadByIdResponse;
    label: string;
    icon?: LucideIcon;
    type?: FieldType;
}

const leadFieldsConfig: LeadFieldConfig[] = [
    { key: 'documento', label: 'CPF / CNPJ', icon: IdCard, type: 'cpfCnpj' },
    { key: 'tipo_pessoa', label: 'Tipo Pessoa', icon: User },
    { key: 'situacao', label: 'Situação', icon: SheetIcon },
    { key: 'natureza_credito', label: 'Natureza', icon: FileText },
    { key: 'valor_liquido', label: 'Valor Líquido', icon: DollarSign, type: 'currency' },
    { key: 'estado_ente_devedor', label: 'Estado', icon: MapPin },
    { key: 'ente_devedor', label: 'Ente Devedor', icon: Building2 },
    { key: 'tentativas_contato', label: 'Tentativas de Contato', icon: MessageSquare },
    { key: 'criado_em', label: 'Criado em', icon: Calendar, type: 'date' },
];

export function LeadSheetInfo({
    leadId,
    setSelectedLeadForDesignateResponsable,
    onClose,
    onOpenNewForm,
    setSelectedLead,
    currentSituation,
    fromCalendar,
}: LeadSheetInfoProps) {

    const [openHistorySheet, setOpenHistorySheet] = useState(false);
    const [shouldFetchHistory, setShouldFetchHistory] = useState(false);

    const { workflowModal, setWorkflowModal } = useLeadTasksTableContext();
    const userInfo = useUserInfoStore((state) => state.data);

    // Deal Memory: sinaliza ao chat que este lead está ativo
    const setActiveLeadId = useBrokerStore((s) => s.setActiveLeadId);
    useEffect(() => {
        if (leadId) setActiveLeadId(leadId);
        return () => setActiveLeadId(null);
    }, [leadId, setActiveLeadId]);
    const { data: leadData, isLoading } = useQuery({
        queryKey: [QueryKeys.leads.leadById, leadId],
        queryFn: () => getLeadById(leadId),
        enabled: !!leadId,
    });

    const {
        data: historyData,
        isLoading: isLoadingHistory,
        isError: isErrorHistory,
        isRefetching: isRefetchingHistory,
    } = useQuery({
        queryKey: [QueryKeys.leads.history, leadId],
        queryFn: () => getLeadsHistory(leadId),
        enabled: shouldFetchHistory && !!leadId,
    });

    const entries = historyData ?? [];

